ciado</label><select class="form-select" id="pathBinding" name="binding_id"><option value="">Sin binding específico / definir después</option><?php foreach($assets as $a)if(($a['logical_type']??'')==='access_point')foreach(($a['bindings']??[]) as $b):?><option value="<?=$b['id']?>" data-ap="<?=$a['id']?>" data-connector="<?= (int)($b['connector_instance_id']??0) ?>" data-type="<?=e($b['external_object_type']??'')?>" data-external="<?=e($b['external_id']??'')?>"><?=e($a['name'].' · '.($b['connector_name']?:'Local').' → '.($b['external_name']?:$b['external_id']?:'equipo'))?></option><?php endforeach;?></select><input type="hidden" name="connector_instance_id" id="pathConnector"><input type="hidden" name="external_object_type" id="pathExternalType"><input type="hidden" name="external_id" id="pathExternalId"></div><div class="col-12 d-flex flex-wrap gap-4"><label><input type="checkbox" name="depends_on_controller" value="1" checked> Depende de la controladora</label><label><input type="checkbox" name="vendor_event_expected" value="1"> Espero evento del fabricante</label><label><input type="checkbox" name="is_primary" value="1"> Ruta principal</label><label><input type="checkbox" name="enabled" value="1" checked> Activa</label></div><div class="col-md-4"><label class="form-label">Pulso (ms)</label><input class="form-control" type="number" name="pulse_ms" placeholder="2000"></div><div class="col-md-8"><label class="form-label">Notas</label><input class="form-control" name="notes" placeholder="Ej.: relé Vimar conectado a entrada REX de inBIO"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar ruta</button></div></form></div></div></div>
<div class="modal fade" id="bindingModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" action="<?=url('asset-binding-save')?>"><?=csrf_field()?><input type="hidden" name="logical_type" id="bindType"><input type="hidden" name="logical_id" id="bindId"><div class="modal-header"><h5 class="modal-title">Vincular <span id="bindName"></span></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-4"><label class="form-label">Función física</label><select class="form-select" name="binding_role" id="bindingRole"><option value="primary">Principal</option><option value="actuator">Actuador / apertura</option><option value="authenticator">Autenticador / lector</option><option value="stream">Stream de video</option><option value="telemetry">Telemetría</option><option value="secondary">Secundario / respaldo</option></select></div><div class="col-md-4"><label class="form-label">Modo de ejecución</label><select class="form-select" name="execution_mode"><option value="realtime">Tiempo real (Property valida y ordena)</option><option value="provisioned">Provisionado (regla queda en fabricante)</option><option value="hybrid">Híbrido</option><option value="passive">Pasivo / lectura</option></select></div><div class="col-md-4"></div><div class="col-12"><label class="form-label">Recurso descubierto</label><select class="form-select" id="externalSelect" required><option value="">Seleccione…</option><?php foreach($external as $x):?><option data-type="<?=e($x['object_type'])?>" data-code="<?=e($x['connector_code']??'')?>" data-domain="<?=e($x['connector_domain']??'')?>" value="<?=e(json_encode(['connector_instance_id'=>(int)$x['connector_instance_id'],'external_object_type'=>$x['object_type'],'external_id'=>$x['external_id'],'external_name'=>$x['name']?:$x['external_code']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES))?>"><?=e($x['connector_name'].' · '.$x['object_type'].' · '.($x['name']?:$x['external_code']?:$x['external_id']))?></option><?php endforeach;?></select><input type="hidden" name="connector_instance_id" id="bindConnector"><input type="hidden" name="external_object_type" id="bindExternalType"><input type="hidden" name="external_id" id="bindExternalId"><input type="hidden" name="external_name" id="bindExternalName"></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Vincular</button></div></form></div></div></div>
<div class="modal fade" id="authModal" tabindex="-1"><div class="modal-dialog modal-lg"><div class="modal-content"><form method="post" action="<?=url('access-authenticator-save')?>"><?=csrf_field()?><div class="modal-header"><h5 class="modal-title">Autenticador de acceso</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-md-6"><label class="form-label">Punto de acceso</label><select class="form-select" name="access_point_id" required><option value="">Seleccione…</option><?php foreach($assets as $a)if($a['logical_type']==='access_point'):?><option value="<?=$a['id']?>"><?=e($a['name'])?></option><?php endif;?></select></div><div class="col-md-6"><label class="form-label">Nombre</label><input class="form-control" name="name" placeholder="Lector QR Lobby" required></div><div class="col-md-4"><label class="form-label">Tipo</label><select class="form-select" name="authenticator_type"><?php foreach(['property_app'=>'Property App','qr'=>'QR','card'=>'Tarjeta','nfc'=>'NFC','pin'=>'PIN','face'=>'Rostro','fingerprint'=>'Huella','lpr'=>'Placa/LPR','intercom'=>'Intercom','button'=>'Pulsador','other'=>'Otro'] as $v=>$l):?><option value="<?=$v?>"><?=$l?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Quién valida</label><select class="form-select" name="validation_owner"><option value="property_hub">Property Hub</option><option value="vendor">Fabricante</option><option value="shared">Compartido</option></select></div><div class="col-md-4"><label class="form-label">Estado</label><select class="form-select" name="status"><option value="planned">Planificado</option><option value="unmapped">Sin mapear</option><option value="online">Operativo</option><option value="offline">Offline</option><option value="disabled">Deshabilitado</option></select></div><div class="col-12 d-flex gap-4"><label><input type="checkbox" name="allow_residents" value="1" checked> Residentes</label><label><input type="checkbox" name="allow_visitors" value="1"> Invitados</label><label><input type="checkbox" name="allow_temporary_credentials" value="1"> Credenciales temporales</label></div></div></div><div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div></form></div></div></div>
<script>document.addEventListener('DOMContentLoaded',()=>{
const role=document.getElementById('bindingRole');
const compatible=(o)=>{if(!o.value)return true;const logical=bindType.value||'',r=role?.value||'primary',t=o.dataset.type||'',code=(o.dataset.code||'').toLowerCase(),domain=(o.dataset.domain||'').toLowerCase(),zk=code==='zkteco'||code==='zkteco_biosecurity';if(logical==='camera'){if(zk||t==='door'||t==='reader')return false;return domain==='video'||['camera','channel','video_channel','stream','nvr_channel','device'].includes(t)||code.includes('onvif')||code.includes('rtsp')||code.includes('video');}if(logical==='access_point'){if(t==='reader')return ['authenticator','secondary','telemetry'].includes(r);if(t==='device')return ['secondary','telemetry'].includes(r);return ['door','relay','lock','barrier','turnstile'].includes(t);}return true;};
const filterExternal=()=>{[...externalSelect.options].forEach((o,i)=>{if(i===0){o.hidden=false;o.disabled=false;return;}const ok=compatible(o);o.hidden=!ok;o.disabled=!ok;});if(externalSelect.selectedOptions[0]?.disabled)externalSelect.value='';externalSelect.dispatchEvent(new Event('change'));};
document.querySelectorAll('.js-bind').forEach(b=>b.addEventListener('click',()=>{bindType.value=b.dataset.type;bindId.value=b.dataset.id;bindName.textContent=b.dataset.name;bindingRole.value=b.dataset.type==='camera'?'stream':'primary';filterExternal();}));
role?.addEventListener('change',filterExternal);
externalSelect.addEventListener('change',()=>{let d={};try{d=JSON.parse(externalSelect.value||'{}')}catch(e){};bindConnector.value=d.connector_instance_id||'';bindExternalType.value=d.external_object_type||'';bindExternalId.value=d.external_id||'';bindExternalName.value=d.external_name||'';});const pb=document.getElementById('pathBinding');if(pb)pb.addEventListener('change',()=>{const o=pb.options[pb.selectedIndex];pathConnector.value=o?.dataset.connector||'';pathExternalType.value=o?.dataset.type||'';pathExternalId.value=o?.dataset.external||'';});});</script><?php endif;?>
